  // Order cruise lines alphabetically by display label (EFFY always first).
  const labelFor=(slug)=>{const cfg=FLEET_CONFIG[slug];return cfg?cfg.label:slug.toUpperCase();};
  slugs.sort((a,b)=>labelFor(a).localeCompare(labelFor(b)));
