const intFmtK=(n)=>{const a=Math.abs(n||0);if(a>=1e6)return`$${(n/1e6).toFixed(2)}M`;if(a>=1e3)return`$${(n/1e3).toFixed(1)}K`;return`$${Math.round(n||0)}`;};
