class ProfileErrorBoundary extends Component{
  constructor(props){super(props);this.state={hasError:false};}
  static getDerivedStateFromError(){return{hasError:true};}
  componentDidUpdate(prev){if(prev.resetKey!==this.props.resetKey&&this.state.hasError)this.setState({hasError:false});}
  render(){
    if(this.state.hasError)return(<div style={{padding:30,textAlign:"center",background:"rgba(255,255,255,0.35)",borderRadius:10,border:"1px solid #E8E0D5"}}><div style={{fontSize:13,color:"#0F766E",fontWeight:700,marginBottom:8}}>This profile could not be displayed</div><div style={{fontSize:11,color:"#8A8578",lineHeight:1.6,marginBottom:14}}>There was an issue rendering this candidate. Use the back button to return to the list. The rest of the dashboard is unaffected.</div><button onClick={this.props.onBack} style={{padding:"8px 18px",borderRadius:6,border:"none",background:"#0F766E",color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer"}}>Back to list</button></div>);
    return this.props.children;
  }
}

