const __storeCache=new Map();// key -> {v:stringified value|null, ts}
const __storeInflight=new Map();// key -> promise (de-dupes concurrent gets)
const STORE_TTL=60000;// 60s freshness window; writes update the cache immediately
const storage={
  async get(k){
    const hit=__storeCache.get(k);
    if(hit&&(Date.now()-hit.ts)<STORE_TTL)return hit.v==null?null:{value:hit.v};
    if(__storeInflight.has(k))return __storeInflight.get(k);
    const p=(async()=>{
      try{
        const r=await fetch("/api/store",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"get",key:k})});
        const d=await r.json();
        const v=(!d||d.value==null)?null:JSON.stringify(d.value);// uniform: stored strings come back quoted so JSON.parse round-trips
        __storeCache.set(k,{v,ts:Date.now()});
        return v==null?null:{value:v};
      }catch{return null;}
      finally{__storeInflight.delete(k);}
    })();
    __storeInflight.set(k,p);
    return p;
  },
  async set(k,v){
    try{
      const parsed=(()=>{try{return JSON.parse(v);}catch{return v;}})();
      const r=await fetch("/api/store",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"set",key:k,value:parsed,token:(typeof window!=="undefined"&&window.__coachToken)||""})});
      const d=await r.json();
      if(d&&d.ok){__storeCache.set(k,{v:typeof v==="string"?v:JSON.stringify(v),ts:Date.now()});return{key:k,value:v};}
      return null;
    }catch{return null;}
  },
  async getPrefix(prefix){
    // One query for every record under a prefix; seeds the cache.
    try{
      const r=await fetch("/api/store",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"getPrefix",prefix})});
      const d=await r.json();
      const map={};
      for(const rec of (d&&d.records)||[]){
        const v=rec.value==null?null:JSON.stringify(rec.value);
        __storeCache.set(rec.key,{v,ts:Date.now()});
        map[rec.key]=v;
      }
      return map;
    }catch{return{};}
  },
};

function buildCoachingDoc(data){
  const esc=(x)=>String(x==null?"":x).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
  const recs=(data&&data.records)||[];
  // group records by type for a readable document
  const spines=recs.filter(r=>String(r.key).startsWith("spine:"));
  const groups=recs.filter(r=>String(r.key)==="group_dev_v1");
  const fmt=(d)=>{try{return new Date(d).toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"});}catch{return d||"";}};
  let body="";
  body+=`<h1>EFFY Development Program</h1>`;
  body+=`<p><b>Coaching Backup</b> · Generated ${esc(fmt(data.exportedAt||new Date().toISOString()))} · ${recs.length} records</p><hr/>`;
  // Individual journeys
  body+=`<h2>Individual Coaching Journeys</h2>`;
  if(!spines.length)body+=`<p>No individual journeys recorded.</p>`;
  spines.forEach(r=>{
    const name=String(r.key).replace("spine:","").replace(/_/g," ");
    let entries=[];try{entries=Array.isArray(r.value)?r.value:JSON.parse(r.value);}catch{}
    if(!entries||!entries.length)return;
    body+=`<h3>${esc(name)}</h3>`;
    entries.forEach(e=>{
      body+=`<p><b>${esc(fmt(e.date))}</b>${e.focus?" · "+esc(e.focus):""}</p>`;
      if(e.feedback)body+=`<p>${esc(e.feedback)}</p>`;
      if(e.directive)body+=`<p><i>Directive:</i> ${esc(e.directive)}</p>`;
      if(e.drill)body+=`<p><i>Action:</i> ${esc(e.drill)}</p>`;
    });
  });
  // Group development
  body+=`<hr/><h2>Group Development</h2>`;
  let gList=[];try{const g=groups[0];gList=g?(Array.isArray(g.value)?g.value:JSON.parse(g.value)):[];}catch{}
  if(!gList.length)body+=`<p>No groups recorded.</p>`;
  gList.forEach(g=>{
    body+=`<h3>${esc(g.name)}</h3>`;
    body+=`<p><i>Members:</i> ${esc((g.members||[]).join(", ")||"none")}</p>`;
    (g.journey||[]).forEach(e=>{
      body+=`<p><b>${esc(fmt(e.date))}</b>${e.focus?" · "+esc(e.focus):""}</p>`;
      if(e.feedback)body+=`<p>${esc(e.feedback)}</p>`;
      if(e.directive)body+=`<p><i>Directive:</i> ${esc(e.directive)}</p>`;
    });
  });
  return `<!DOCTYPE html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><title>EFFY Coaching Backup</title><style>body{font-family:Calibri,Arial,sans-serif;font-size:11pt;color:#1a1a1a;}h1{color:#0F766E;font-size:20pt;}h2{color:#0F766E;font-size:14pt;border-bottom:1px solid #ccc;padding-bottom:3px;}h3{color:#111;font-size:12pt;margin-top:14px;}p{margin:3px 0;}i{color:#555;}</style></head><body>${body}</body></html>`;
}
